Definition wa_words_exit (ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a7 s2 s3 s4 s5 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D n : Z) : machine_state -> Prop :=
  fun ms' => exists (a0' a6' s6' s7' s8' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0' (Z_to_bv 64 (4 * n)) a2 a3 a4 a5 a6' a7 s2 s3 s4 s5 s6' s7' s8' s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0xb1830) fc None m' (seg_rom asegs)
    /\ munch [(D, D + 4 * n)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma wa_words_loop : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a7 s2 s3 s6 s7 s8 s9 s10 s11 t3 t6 : word) F fc (m : mem) (SA DA n : Z),
  Z.of_nat k = n - j -> 0 <= j -> (1 <= k)%nat -> n < 2^26 ->
  0 < SA -> SA mod 4 = 0 -> SA + 4 * n <= 2^47 -> 0 < DA -> DA mod 4 = 0 -> DA + 4 * n <= 2^47 ->
  (DA + 4 * n <= 0x7fff7000 \/ 0x10007fff8000 <= DA) ->
  wr_at asegs m SA (4 * n) -> acc asegs m SA (4 * n) -> wr_at asegs m DA (4 * n) -> acc asegs m DA (4 * n) -> mem_inv asegs m ->
  evt asegs (wa_words_exit ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 (Z_to_bv 64 2147450880) a7 s2 s3 (Z_to_bv 64 SA) (Z_to_bv 64 DA) s9 s10 s11 t3 (Z_to_bv 64 SA) (Z_to_bv 64 DA) t6 F fc m DA n)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 (4 * j)) a2 a3 a4 (Z_to_bv 64 2147450880) (Z_to_bv 64 (j - n)) a7 s2 s3 (Z_to_bv 64 SA) (Z_to_bv 64 DA)
             s6 s7 s8 s9 s10 s11 t3 (Z_to_bv 64 SA) (Z_to_bv 64 DA) t6)
        F (Z_to_bv 64 0xb17c8) fc None m (seg_rom asegs)).
